package com.ryanjei.orushio.pve.core;
import static org.junit.jupiter.api.Assertions.*;
import com.ryanjei.orushio.pve.application.*;import com.ryanjei.orushio.pve.domain.GameSession;import java.util.*;import org.junit.jupiter.api.Test;
class GameCoreProgressListenerTest{
 @Test void FinalCoreはPaperEvent外へCLEARと共通Recoveryを順序dispatchする(){FakeGames games=new FakeGames();List<Runnable>queued=new ArrayList<>();GameCoreProgressListener listener=new GameCoreProgressListener((id,count)->{},()->games,queued::add);UUID session=UUID.randomUUID();listener.finalCoreDestroyed(session);assertTrue(games.events.isEmpty());assertEquals(1,queued.size());queued.getFirst().run();assertEquals(List.of("clear:"+session,"recover:"+session),games.events);}
 @Test void 通常Core進行は既存Tier接続へ渡す(){List<String>events=new ArrayList<>();UUID session=UUID.randomUUID();new GameCoreProgressListener((id,count)->events.add(id+":"+count),FakeGames::new,Runnable::run).normalCoreDestroyed(session,2,3);assertEquals(List.of(session+":2"),events);}
 private static final class FakeGames implements GameApplicationService{final List<String>events=new ArrayList<>();public GameSession current(){return GameSession.idle();}public OperationResult startRecruiting(String s){throw new UnsupportedOperationException();}public OperationResult closeRecruiting(String s){throw new UnsupportedOperationException();}public OperationResult startMapSetup(String s){throw new UnsupportedOperationException();}public void validateMapSetup(String s){}public OperationResult closeMapSetup(String s){throw new UnsupportedOperationException();}public OperationResult completeGame(UUID id){events.add("clear:"+id);return new OperationResult("o",id.toString(),"CLEAR");}public OperationResult recoverClearGame(UUID id){events.add("recover:"+id);return new OperationResult("o",id.toString(),"IDLE");}}
}
